ROOT = Path(__file__).resolve().parent
U = 'unavailable'
now = lambda: datetime.now(timezone.utc).isoformat()
def stamp(p):
    return datetime.fromtimestamp(p.stat().st_mtime, timezone.utc).isoformat()

