sources=[]
for id,year,pmc,title,doi,pmid,authors in source_specs:
    p=ROOT/'snapshots'/f'{id}_fulltext.html' if pmc else ROOT/'snapshots'/f'{id}_open.txt'
    if pmc:
        raw=p.read_text()
        authors=[html.unescape(a) for a in re.findall(r'<meta name="citation_author" content="([^"]+)"',raw)] or authors
        m=re.search(r'<meta name="citation_pmid" content="([^"]+)"',raw)
        if m: pmid=m.group(1)
    note='Primary publication snapshot; supplementary captions embedded in main page reviewed where used. Standalone supplementary files and raw individual-level data not downloaded.'
    if id=='G02': note+=' Human and mouse experiments have separate cohorts. Author correction DOI 10.1038/s41586-018-0227-7 (2018) is retained as metadata/indexed excerpt in G02correction_retrieval.txt, search_01.json and Gsearch7_retrieval.txt. Correction full text not obtained; no EDEL steady-state Treg percentage assertion is extracted.'
    if id=='G06': note='OneK1K anchor evaluated at abstract level: 982 donors, 1,267,758 PBMCs, 14 cell types. No molecule-specific assertion extracted from aggregate coverage. Publisher full-text request returned 403. MR language in abstract is not accepted as experimental variant causality.'
    if id=='G08': note='Abstract-only historical association anchor. Functional assay methods and cohort-level membership not verified here; only disease association is extracted.'
    sources.append(dict(source_id=id,title=title,authors=authors,year=year,url=f'https://pmc.ncbi.nlm.nih.gov/articles/{pmc}/' if pmc else f'https://pubmed.ncbi.nlm.nih.gov/{pmid}/',doi=doi,pmid=pmid,source_type='primary_study',version=f'{year} primary publication; exact publisher revision unavailable',retrieved_at=stamp(p),access_level='full_text' if pmc else 'abstract_and_metadata',snapshot_path=str(p.relative_to(ROOT.parent.parent)),species=['Homo sapiens','Mus musculus'] if id=='G02' else 'Homo sapiens',notes=note))

