    d.update(cohort_id=id,dataset_id=id.replace('GCO','GDS'),study_id=study,species='Homo sapiens',tissue='peripheral blood',disease='healthy',independence_status='unresolved',related_publications=[study]);d.update(kw);cohorts.append(d)
