assertions=[]
fields=['assertion_id','subject','subject_type','predicate','object','object_type','subject_layer','object_layer','measurement','evidence_tier','direction','source_id','cohort_id','source_locator','evidence_summary','species','ancestry','age','sex','tissue','disease','disease_severity','treatment_status','cell_type','cell_state','developmental_state','stimulation','dose','duration','assay','genomic_background','time_point','effect_size','effect_unit','uncertainty','causal_directness','limitations','contradiction_group','candidate_path','qc_status','qualitative_confidence']
C={c['cohort_id']:c for c in cohorts}
def add(id,src,co,subject,predicate,obj,summary,locator,**kw):
 d={k:U for k in fields};c=C[co]
 d.update(assertion_id=id,source_id=src,cohort_id=co,subject=subject,subject_type='variant',predicate=predicate,object=obj,object_type='gene',subject_layer='G',object_layer='T',measurement='RNA_abundance',evidence_tier='G2',direction='association',source_locator=locator,evidence_summary=summary,species=c['species'],ancestry=c['ancestry'],tissue=c['tissue'],disease=c['disease'],cell_type=c['cell_type'],uncertainty='Effect estimate and confidence interval unavailable unless explicitly supplied; cohort/state-specific evidence.',causal_directness='Genotype association with molecular trait; linked variants and residual confounding remain possible.',limitations='No automatic transport across cell type, stimulation, ancestry, tissue or molecular layer.',qc_status='reviewed_extraction',qualitative_confidence='moderate')
 d.update(kw);assertions.append(d)

